import { readToolExportJson } from '../save/access/json'
import { GAME_EXPORT_REQUIRED_MESSAGE } from './encrypted'
export { isEncryptedSave, GAME_EXPORT_REQUIRED_MESSAGE } from './encrypted'

function toBytes(input: Uint8Array | ArrayBuffer): Uint8Array {
  return input instanceof Uint8Array ? input : new Uint8Array(input)
}

/** Signature detector retained for importers that explain unsupported legacy files. */
export function isGzipped(input: Uint8Array | ArrayBuffer): boolean {
  const bytes = toBytes(input)
  return bytes.length >= 2 && bytes[0] === 0x1f && bytes[1] === 0x8b
}

/** Parse the official game's External Tools Export into a canonical account root. */
export async function decodeSaveFile(input: Uint8Array | ArrayBuffer): Promise<Record<string, unknown>> {
  return decodeInflatedSave(toBytes(input))
}

/** Parse official export JSON already loaded by a worker or another file reader. */
export function decodeInflatedSave(bytes: Uint8Array): Record<string, unknown> {
  const root = readToolExportJson(bytes)
  if (!root) throw new Error(GAME_EXPORT_REQUIRED_MESSAGE)
  return root
}
